   String login=row.optString("login","");if(importing&&!login.isBlank()){need(login.matches(type.name().toLowerCase()+"[1-9][0-9]{0,5}"),"Account login must match its type and a positive number");number=Integer.parseInt(login.replaceFirst("^[a-z]+",""));}
   need(type!=ClientType.Type.TEAM||number<TestTeamPolicy.NUMBER,"The diagnostic account number is reserved");ClientId client=new ClientId(site,type,number);need(s.model().getAccount(client)==null&&used.add(site+":"+client.getName()),"Duplicate or existing account: "+client.getName());next.put(key,number+1);
