 static JSONObject query(DashboardBridge s,JSONObject a)throws Exception{
  String section=string(a,"section",40);if(TYPES.containsKey(section))return rows(s,section);
  return switch(section){
   case "autojudges"->autoJudges(s);case "connections"->connections(s);case "notifications"->notifications(s);case "scoring"->scoring(s);case "deliveries"->balloons(s);case "inputValidation"->inputValidation(s);
   case "playback"->{JSONArray out=new JSONArray();Set<String> imported=new HashSet<>();Path base=s.privateBase.resolve("replays");if(Files.isDirectory(base))try(var stream=Files.list(base)){for(Path dir:stream.toList())if(Files.isRegularFile(dir.resolve("dataset.json"))){JSONObject d=new JSONObject(Files.readString(dir.resolve("dataset.json")));String id="prepared:"+dir.getFileName();PlaybackInfo nativeInfo=null;String filename=dir.resolve(d.getString("main")).toRealPath().toString();for(PlaybackInfo candidate:s.model().getPlaybackInfos())if(filename.equals(candidate.getFilename()))nativeInfo=candidate;if(nativeInfo!=null)imported.add(nativeInfo.getElementId().toString());out.put(new JSONObject().put("id",id).put("name",d.getString("name")).put("active",false).put("ready",true).put("started",nativeInfo!=null&&nativeInfo.isStarted()).put("sequence",nativeInfo==null?0:nativeInfo.getSequenceNumber()).put("events",d.getInt("events")));}}for(PlaybackInfo p:s.model().getPlaybackInfos())if(!imported.contains(p.getElementId().toString()))out.put(new JSONObject().put("id",p.getElementId().toString()).put("name",p.getDisplayName()).put("active",p.isActive()).put("ready",false).put("started",p.isStarted()).put("sequence",p.getSequenceNumber()).put("events",p.getReplayList()==null?0:p.getReplayList().length));yield new JSONObject().put("rows",out);}
   case "shadow"->{ContestInformation info=s.model().getContestInformation();yield new JSONObject().put("enabled",info.isShadowMode()).put("testMode",info.isCcsTestMode()).put("url",info.getPrimaryCCS_URL()).put("configured",info.getPrimaryCCS_user_login()!=null&&!info.getPrimaryCCS_user_login().isBlank()).put("lastEvent",info.getLastShadowEventID()).put("note","Shadow comparison depends on a configured primary CCS and deployed feed integration. Native result/contest comparison reports are available in Native Reports. Remote credentials and host commands are not exposed through this page.");}
   case "plugins"->{JSONArray out=new JSONArray();for(var plugin:s.control().getPluginList())out.put(new JSONObject().put("title",plugin.getPluginTitle()).put("class",plugin.getClass().getName()));yield new JSONObject().put("rows",out).put("note","Installed native Java UI plugins can be inspected here. Loading arbitrary JVM classes or desktop Swing windows is outside the isolated web runtime.");}
   case "eventfeeds"->{JSONArray out=new JSONArray();EventFeedDefinition[] definitions;try{definitions=s.model().getEventFeedDefinitions();}catch(NullPointerException uninitialized){definitions=new EventFeedDefinition[0];}for(EventFeedDefinition d:definitions)out.put(new JSONObject().put("id",d.getElementId().toString()).put("name",d.getDisplayName()).put("port",d.getPort()).put("active",d.isActive()).put("frozen",d.isFrozen()));yield new JSONObject().put("rows",out).put("note","The installed PC2 event-feed editor has empty add/update methods. Use native JSON/XML report downloads; no additional listener is exposed.");}
   default->throw new IllegalArgumentException("Unknown native section");
  };
 }
